INSERT INTO meal_recipes (id, name, description, instructions, servings, calories_per_serving, protein_g, fat_g, carb_g, goal_tags, serving_notes, tips, expert_advice, suggested_combo, created_at, updated_at) VALUES ('recipe-ga-nuong-noi-dat', 'Gà nướng nồi đất', 'Gà nướng nồi đất mềm thơm, đậm đà, làm mới bữa cơm nhà', 'Chưa có hướng dẫn chi tiết.', 1, 0, 0, 0, 0, NULL, 'Bày gà nướng nồi đất ra bàn dùng kèm cơm. Chấm thêm xốt phô mai cay “Aji xốt”.', 'Khứa đùi gà khi ướp để thịt gà thấm gia vị và mau chín.Nướng gà trong nồi đất, gà sẽ chín mềm ngọt thịt và không bị khô.', '– Món ăn này cần áp dụng đồng thời với thực đơn đã được hướng dẫn thì mới có tác dụng xây dựng khối cơ xương– Để lượng chất đạm trong khẩu phần có thể đạt được mục tiêu là dùng để xây dựng khối cơ xương chứ không dùng để sinh năng lượng, cần thiết phải ăn đủ lượng chất bột đường để sử dụng làm năng lượng cho các tế bào trong cơ thể, dành toàn bộ chất đạm cho việc xây dựng cấu trúc cơ thể. Khi ăn không đủ lượng chất bột đường, một phần chất đạm ăn vào sẽ được sử dụng để sinh năng lượng hoạt động, lúc đó sẽ làm tăng các chất chuyển hóa có ni tơ (amoniac, ure, creatinin…) trong máu, làm tăng tải cho gan, thận và hệ thống chuyển hóa trong các tế bào, chưa kể quá trình tăng thải các chất chuyển hóa này quá nước tiểu có thể kéo theo sự mất mát nhiều dạng chất khoáng trong đó có Canxi, tức là làm tăng nguy cơ mất xương, ngày cả khi khối cơ có vẻ tăng lên.', NULL, '2026-08-07T22:02:58.523Z', '2026-08-07T22:02:58.523Z');
